salida.respuesta_modelo:
{
  "accion": "corregir",
  "mensaje": "Falta una afirmación específica sobre el proceso de reincorporación y el rol del Decano según RG-ART-033.",
  "apoyos": [
    {
      "afirmacion": "El estudiante debe solicitar su reincorporación al Vicedecano",
      "fuente": "RI-FI-ART-027",
      "extracto": "La y el estudiante con suspensión de estudios deberá solicitar su reincorporación a la Vicedecanatura para continuarlos."
    },
    {
      "afirmacion": "El estudiante debe adjuntar certificados de no deudas",
      "fuente": "RG-ART-035",
      "extracto": "a) Certificado de la División de Asistencia Financiera al Estudiante en que conste que el alumno no tiene deudas con la universidad por concepto de aranceles y préstamos o que el pago de dichas deudas ha sido debidamente garantizado;"
    },
    {
      "afirmacion": "En caso de salud, se requiere oficio oficial",
      "fuente": "RG-ART-033",
      "extracto": "el alumno deberá acompañar los antecedentes oficiales tales como el informe de la Dirección de Servicios Estudiantiles, o la Unidad que corresponda en Chillán y Los Ángeles, u otros fidedignos, que demuestren que han cesado los impedimentos que justificaron la suspensión"
    },
    {
      "afirmacion": "La reincorporación puede extenderse por tres años",
      "fuente": "RG-ART-033",
      "extracto": "la suspensión de estudios podrá extenderse por un período máximo de tres años calendario."
    },
    {
      "afirmacion": "Se regirá por el plan de estudio vigente",
      "fuente": "RI-FI-ART-028",
      "extracto": "Los alumnos que solicitan su reincorporación deberán adscribirse al Plan de Estudio que se esté impartiendo a la fecha de su reincorporación excepto el caso de los alumnos en intercambio quienes se mantendrán en el mismo plan de estudio."
    }
  ]
}

